/** Offline exercise/full-lifecycle evaluator. Never opens credentials or calls a host/database. */
import{readFile}from'node:fs/promises';import{readM78ContinuationJournal,cleanM78ContinuationJournal,readM78ContinuationRestart}from'../../tools/staging/check-m78-continuation';import{readM78Continuation4Diagnostics}from'../../tools/staging/check-m78-continuation4';import{decodeScope1Register}from'../../apps/site-web/src/lib/m78-api';import{m78CanonicalJson as canonical}from'../../packages/neuvetra-database/src/m78-validation';
const sha=(b:string|Uint8Array)=>new Bun.CryptoHasher('sha256').update(b).digest('hex'),check=(v:unknown,m:string)=>{if(!v)throw Error(m)},same=(a:unknown,b:unknown)=>canonical(a)===canonical(b);
type Pin={path:string;sha256:string};export interface LifecycleAdmission{journalSha256:string;journalHead:string;diagnosticsSha256:string;diagnosticsHead:string;baselineResult:Pin;restartAttestation?:Pin}
type Loader=(path:string)=>Promise<string>;
export function verifyLifecycleDiagnostics(text:string,a:LifecycleAdmission,full:boolean){check(sha(text)===a.diagnosticsSha256,'diagnostic bytes');const es=readM78Continuation4Diagnostics(text),modes=full?['baseline','exercise','revisit']:['baseline','exercise'],phases:any[]=[];let phase:any[]=[];for(const e of es){if(e.kind==='phase_started'){check(!phase.length,'nested phase');phase=[e]}else{check(phase.length,'event outside phase');phase.push(e);if(e.kind==='phase_finished'){phases.push(phase);phase=[]}}}check(!phase.length&&phases.length===modes.length,'phase count');for(let n=0;n<modes.length;n++){const p=phases[n]!,mode=modes[n]!,first=p[0],last=p.at(-1);check(first.mode===mode&&last.mode===mode&&first.data.transport?.keepalive===false&&first.data.transport?.retries===0&&last.data.status==='passed'&&last.data.paused===false&&last.data.diagnosticsHealthy===true&&last.data.applicationPostRequests===(mode==='exercise'?37:0)&&last.data.allCreatedAuthSessionsClosed===true,'phase closure');let ordinal=0,appPosts=0;const open=new Set<number>();for(const e of p.slice(1,-1)){check(e.mode===mode,'phase mode');if(e.kind==='request_intent'){check(e.data.ordinal===++ordinal,'ordinal reset/order');open.add(ordinal);if(e.data.method==='POST'&&String(e.data.route).startsWith('application:'))appPosts++}else if(e.kind==='response_headers'){check(open.delete(e.data.ordinal),'paired response')}else check(false,'diagnostic error/extra')}check(open.size===0&&appPosts===(mode==='exercise'?37:0),'complete outcomes/posts')}check(es.at(-1)?.sha256===a.diagnosticsHead,'diagnostic head');return{events:es.length,phases:phases.length}}
export async function verifyContinuation4Lifecycle(text:string,diagnosticText:string,a:LifecycleAdmission,load:Loader=path=>readFile(path,'utf8')){check(sha(text)===a.journalSha256,'journal bytes');const first=JSON.parse(text.split('\n')[0]!),events=readM78ContinuationJournal(text,first.workspaceId);cleanM78ContinuationJournal(events);check(events.at(-1)?.sha256===a.journalHead,'journal head');const baselineText=await load(a.baselineResult.path);check(sha(baselineText)===a.baselineResult.sha256,'baseline result pin');const baseline=JSON.parse(baselineText);check(baseline.status==='m78_independent_continuation4_hosted_baseline_passed'&&baseline.journalPath==='.superpowers/m78-hosted-continuation4.jsonl','accepted baseline');const bytes=new TextEncoder().encode(text),prefix=new TextDecoder().decode(bytes.slice(0,baseline.verifiedPrefixBytes));check(sha(prefix)===baseline.prefixSha256&&readM78ContinuationJournal(prefix,first.workspaceId).at(-1)?.sha256===baseline.headSha256,'exact baseline prefix');const finishes=events.filter(e=>e.kind==='attempt_finished'),full=finishes.some(e=>e.mode==='revisit');check(finishes.map(e=>e.mode).join(',')===(full?'baseline,exercise,revisit':'baseline,exercise'),'phase order');const starts=events.filter(e=>e.kind==='attempt_started');check(starts.every(e=>same(e.data.gate,starts[0]!.data.gate)),'one gate');const exercise=events.find(e=>e.kind==='exercise_complete')!,exerciseFinish=finishes.find(e=>e.mode==='exercise')!;check(exercise&&exercise.data.applicationPostRequests===37,'exercise terminal');const posts=events.filter(e=>e.mode==='exercise'&&e.kind==='post_intent'),outcomes=events.filter(e=>e.mode==='exercise'&&e.kind==='post_outcome'),verified=events.filter(e=>e.mode==='exercise'&&e.kind==='post_verified');check(posts.length===37&&outcomes.length===37&&verified.length===37&&posts[0]?.data.name==='m78_initial_unreviewed_report'&&!posts.some(e=>e.data.name==='m78_initial_blocked_inventory')&&outcomes.every(e=>e.data.status===201),'exact37');const decoded=await decodeScope1Register(exercise.data.scope1,first.workspaceId);check(same(decoded,exercise.data.scope1)&&decoded.reconciliation.status==='reconciled_bounded_synthetic'&&decoded.reconciliation.totals?.company.kgCo2eExact==='126850.17632025'&&decoded.process.versions.length===1&&decoded.inventory.versions.length===2&&decoded.process.reports.length===2&&decoded.inventory.reports.length===3,'decoded final state');const baseEvent=events.find(e=>e.kind==='baseline')!;check(same(decoded.inventory.versions[0],baseEvent.data.scope1.inventory.versions[0])&&same(exercise.data.legacy,baseEvent.data.legacy),'history/legacy retained');verifyLifecycleDiagnostics(diagnosticText,a,full);if(full){check(a.restartAttestation,'restart pin');const revisit=events.find(e=>e.kind==='revisit_verified')!;check(revisit.data.exerciseSha256===exercise.sha256&&revisit.data.applicationPostRequests===0&&revisit.data.exactRetainedState===true,'revisit exact');await readM78ContinuationRestart({gate:starts[0]!.data.gate,restartAttestation:a.restartAttestation}as any,exerciseFinish.createdAt,load)}else check(!a.restartAttestation,'exercise-only before restart');return{status:full?'m78_independent_continuation4_full_lifecycle_passed':'m78_independent_continuation4_exercise_passed',events:events.length,applicationPostRequests:37,reports:5,grossKgCo2eExact:'126850.17632025',actualRestartVerified:full,hostedCalls:0}}

import{test,expect}from'bun:test';import{verifyLifecycleDiagnostics}from'./m78-continuation4-lifecycle-independent-review';import{m78CanonicalJson as canonical}from'../../packages/neuvetra-database/src/m78-validation';
const sha=(s:string)=>new Bun.CryptoHasher('sha256').update(s).digest('hex');
function diagnostics(full=true){const es:any[]=[],add=(mode:string,kind:string,data:any)=>{const body={sequence:es.length+1,previousSha256:es.at(-1)?.sha256??null,profile:'m78-continuation4-diagnostic-v1',mode,kind,data,createdAt:new Date(100000+es.length).toISOString()},hash=sha(canonical(body));es.push({...body,sha256:hash})};for(const mode of(full?['baseline','exercise','revisit']:['baseline','exercise'])){add(mode,'phase_started',{transport:{runtime:'bun-fetch',pooling:'disabled',keepalive:false,retries:0}});let ordinal=0;for(let n=0;n<(mode==='exercise'?37:0);n++){add(mode,'request_intent',{ordinal:++ordinal,method:'POST',route:'application:/workspace-api/workspace/:id/scope1-inventory'});add(mode,'response_headers',{ordinal,status:201})}add(mode,'phase_finished',{status:'passed',paused:false,diagnosticsHealthy:true,applicationPostRequests:mode==='exercise'?37:0,allCreatedAuthSessionsClosed:true})}const text=es.map((e:any)=>JSON.stringify(e)).join('\n')+'\n';return{text,head:es.at(-1).sha256,events:es}}
test.each([false,true])('admits continuous %s lifecycle diagnostics with per-phase ordinal reset',full=>{const f=diagnostics(full),a:any={diagnosticsSha256:sha(f.text),diagnosticsHead:f.head};expect(verifyLifecycleDiagnostics(f.text,a,full).phases).toBe(full?3:2)});
test('rejects retries, pooling, ordinal gaps, missing outcomes, wrong phase posts and errors',()=>{for(const mutate of[(e:any[])=>e[0].data.transport.keepalive=true,(e:any[])=>e[0].data.transport.retries=1,(e:any[])=>e.find(x=>x.kind==='request_intent').data.ordinal=2,(e:any[])=>e.splice(e.findIndex(x=>x.kind==='response_headers'),1),(e:any[])=>e.find(x=>x.mode==='baseline'&&x.kind==='phase_finished').data.applicationPostRequests=1,(e:any[])=>{const i=e.findIndex(x=>x.kind==='response_headers');e[i]={...e[i],kind:'request_error'}}]){const f=diagnostics();mutate(f.events);let previous:null|string=null;for(let i=0;i<f.events.length;i++){const e=f.events[i],body={sequence:i+1,previousSha256:previous,profile:e.profile,mode:e.mode,kind:e.kind,data:e.data,createdAt:e.createdAt};e.sequence=i+1;e.previousSha256=previous;e.sha256=sha(canonical(body));previous=e.sha256}const text=f.events.map((e:any)=>JSON.stringify(e)).join('\n')+'\n';expect(()=>verifyLifecycleDiagnostics(text,{diagnosticsSha256:sha(text),diagnosticsHead:previous}as any,true)).toThrow()}});
test('hash and head pins are mandatory',()=>{const f=diagnostics();expect(()=>verifyLifecycleDiagnostics(f.text,{diagnosticsSha256:'0'.repeat(64),diagnosticsHead:f.head}as any,true)).toThrow();expect(()=>verifyLifecycleDiagnostics(f.text,{diagnosticsSha256:sha(f.text),diagnosticsHead:'0'.repeat(64)}as any,true)).toThrow()});
